    // Galois LFSR shift/XOR rule:
    // New bit [4] = old bit [0]
    // New bit [3] = old bit [4]
    // New bit [2] = old bit [3] ^ old bit [0] (tap at position 2 corresponds to bit 2)
    // New bit [1] = old bit [2]
    // New bit [0] = old bit [1] ^ old bit [0] (tap at position 4 corresponds to bit 0)
    function [4:0] lfsr_next;
