            lfsr_next[4] = out_bit;
            lfsr_next[3] = current[4];
            lfsr_next[2] = current[3] ^ out_bit;
            lfsr_next[1] = current[2];
            lfsr_next[0] = current[1] ^ out_bit;
        end
    endfunction

