            #1; // small delay for propagation

            // Compute what the next state SHOULD be based on golden model
            expected_q = lfsr_next(expected_q);

            // 4-State Output Equality check using !==
            if (q !== expected_q) begin
                $display("ERROR at cycle %0d: Expected q = %b, got q = %b", cycle_count, expected_q, q);
                errors = errors + 1;
            end

            // Also check that it never hits 0's
            if (q === 5'b00000) begin
                $display("ERROR: LFSR entered all-zero state!");
                errors = errors + 1;
            end

            cycle_count = cycle_count + 1;
        end

        // Test synchronous reset mid-stream
        @(negedge clk);
        reset = 1;
        @(posedge clk);
        #1;
